import operator

OPS = {
    "=": operator.eq,
    "!=": operator.ne,
    "<": operator.lt,
    "<=": operator.le,
    ">": operator.gt,
    ">=": operator.ge,
}


class Query:
    def __init__(self, rows: list[dict], _columns=None, _filters=()):
        self._rows = rows
        self._columns = _columns
        self._filters = tuple(_filters)

    def _copy(self, **changes) -> "Query":
        state = {"_columns": self._columns, "_filters": self._filters}
        state.update(changes)
        return Query(self._rows, **state)

    def select(self, *columns: str) -> "Query":
        return self._copy(_columns=columns or None)

    def where(self, column: str, op: str, value) -> "Query":
        if op not in OPS:
            raise ValueError(f"unsupported operator {op!r}")
        return self._copy(_filters=(*self._filters, (column, OPS[op], value)))

    def run(self) -> list[dict]:
        out = []
        for row in self._rows:
            if all(row.get(c) is not None and fn(row[c], v) for c, fn, v in self._filters):
                if self._columns is None:
                    out.append(dict(row))
                else:
                    out.append({c: row.get(c) for c in self._columns})
        return out

