        present = [r for r in rows if r.get(column) is not None]
        missing = [r for r in rows if r.get(column) is None]
        present.sort(key=lambda r: r[column], reverse=descending)
        rows = present + missing
    return rows


AGGREGATES = ("count", "sum", "avg", "min", "max")


def _aggregate(func: str, column, rows: list[dict]):
    if func == "count":
        return len(rows) if column is None else sum(1 for r in rows if r.get(column) is not None)
    values = [r[column] for r in rows if r.get(column) is not None]
    if not values:
        return None
    if func == "sum":
        return sum(values)
    if func == "avg":
        return round(sum(values) / len(values), 2)
    return min(values) if func == "min" else max(values)


def _group(rows: list[dict], keys: tuple, aggregates: dict) -> list[dict]:
    groups: dict[tuple, list[dict]] = {}
    for r in rows:
        groups.setdefault(tuple(r.get(k) for k in keys), []).append(r)
    if not keys and not groups:
        groups[()] = []  # an aggregate over zero rows still yields one row
    out = []
    for key, members in groups.items():
        row = dict(zip(keys, key))
        for alias, (func, column) in aggregates.items():
            row[alias] = _aggregate(func, column, members)
        out.append(row)
    return out


