        row = dict(zip(keys, key))
        for alias, (func, column) in aggregates.items():
            row[alias] = _aggregate(func, column, members)
        out.append(row)
    return out


def _join(left: list[dict], right: list[dict], left_on: str, right_on: str, how: str) -> list[dict]:
    index: dict[object, list[dict]] = {}
    right_columns: dict[str, None] = {}
    for r in right:
        for c in r:
            if not (c == right_on and left_on == right_on):
                right_columns.setdefault(c)
        if r.get(right_on) is not None:
            index.setdefault(r[right_on], []).append(r)

    def merge(l_row: dict, r_row: dict) -> dict:
        out = dict(l_row)
        for c in right_columns:
            out[f"{c}_right" if c in l_row else c] = r_row.get(c)
        return out

    out = []
    for l_row in left:
        key = l_row.get(left_on)
        matches = index.get(key, []) if key is not None else []
        if matches:
            out.extend(merge(l_row, m) for m in matches)
        elif how == "left":
            out.append(merge(l_row, {}))
    return out


