    def __init__(self, rows: list[dict], **state):
        self._rows = rows
        self._state = {
            "columns": None, "filters": (), "order": (), "limit": None, "offset": 0,
            "group": None, "aggregates": {}, "joins": (),
        }
        self._state.update(state)

    def _copy(self, **changes) -> "Query":
        return Query(self._rows, **{**self._state, **changes})

    def select(self, *columns: str) -> "Query":
        return self._copy(columns=columns or None)

    def where(self, column: str, op: str, value) -> "Query":
