        return self._copy(order=(*self._state["order"], (column, descending)))

    def limit(self, n: int, offset: int = 0) -> "Query":
        return self._copy(limit=n, offset=offset)

    def group_by(self, *columns: str) -> "Query":
        return self._copy(group=columns)

    def aggregate(self, **aliases: tuple) -> "Query":
        for alias, (func, _column) in aliases.items():
            if func not in AGGREGATES:
                raise ValueError(f"unsupported aggregate {func!r} for {alias!r}")
        return self._copy(aggregates={**self._state["aggregates"], **aliases})

    def join(self, rows: list[dict], left_on: str, right_on: str, how: str = "inner") -> "Query":
        if how not in ("inner", "left"):
            raise ValueError(f"unsupported join type {how!r}")
        return self._copy(joins=(*self._state["joins"], (rows, left_on, right_on, how)))

    def run(self) -> list[dict]:
        s = self._state
        rows = self._rows
        for right, left_on, right_on, how in s["joins"]:
            rows = _join(rows, right, left_on, right_on, how)
