        end = None if s["limit"] is None else s["offset"] + s["limit"]
        rows = rows[s["offset"]:end]
        if s["columns"] is None:
            return [dict(r) for r in rows]
        return [{c: r.get(c) for c in s["columns"]} for r in rows]
